// HasOrders applies the HasEdge predicate on the "orders" edge.
func HasOrders() predicate.HotelOffer {
	return predicate.HotelOffer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, OrdersTable, OrdersColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrdersWith applies the HasEdge predicate on the "orders" edge with a given conditions (other predicates).
func HasOrdersWith(preds ...predicate.TravelOrder) predicate.HotelOffer {
	return predicate.HotelOffer(func(s *sql.Selector) {
		step := newOrdersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.HotelOffer) predicate.HotelOffer {
	return predicate.HotelOffer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.HotelOffer) predicate.HotelOffer {
	return predicate.HotelOffer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.HotelOffer) predicate.HotelOffer {
	return predicate.HotelOffer(sql.NotPredicates(p))
}
